    "id": "lv-larian-studios-1461a85a-b36c-4b96-974d-6e3e7dcd5cf9",
    "title": "RPG Designer | Concepteur des Jeux de rôle",
    "company": "Larian Studios",
    "locations": [
      "Quebec"
    ],
    "remote": false,
    "salary": null,
